mapper.select:
select ft.T_Name as tName, ft.T_Code as tCode, ft.T_Type as tType, mn.* from SYS_FileTemplate_Print mn left join SYS_FileTemplate ft on ft.T_Id=mn.T_Id
1=1
and ft.T_Type = #{params.tType}
and mn.T_Id = #{params.tId}
and INSTR(mn.Tp_Name,#{params.tpName})
and INSTR(ft.T_Name,#{params.tName})
and INSTR(ft.T_Code,#{params.tCode})
and mn.Te_Id = #{params.teId}
and (mn.Tp_State = #{params.tpState} or mn.Tp_State is null)
and mn.Tp_State = #{params.tpState}
order by mn.${params.sortFiled} ${params.sortType}
order by (case when mn.Tp_Order is null or mn.Tp_Order = 0 then 1 else 0 end) asc, mn.Tp_Order asc, mn.Tp_Create_Time desc
limit #{params.start},#{params.size}

select
count(1)
from  SYS_FileTemplate_Print mn
left join  SYS_FileTemplate ft on ft.T_Id=mn.T_Id

    1=1
    
        and ft.T_Type = #{params.tType}
    
    
        and mn.T_Id = #{params.tId}
    
    
        and INSTR(mn.Tp_Name,#{params.tpName})
    
    
        and INSTR(ft.T_Name,#{params.tName})
    
    
        and INSTR(ft.T_Code,#{params.tCode})
    
    
        and mn.Te_Id = #{params.teId}
    
    
        
            
                and (mn.Tp_State = #{params.tpState} or mn.Tp_State is null)
            
            
                and mn.Tp_State = #{params.tpState}
            
        
    
    
        and mn.Tp_Id not in
        
            #{tpId}
